# patch-labs.ps1
# Safely patches src/Labs.js to replace the old multiple-choice ticket lab
# with the new AI-generated / AI-scored ticket simulator.
#
# All replacement text is embedded as Base64 to avoid here-string
# terminator issues that can occur when a file is downloaded/transferred.
#
# Run from the project root: C:\Users\marcu\tiershift-academy
#   .\patch-labs.ps1

$ErrorActionPreference = "Stop"
$labsPath = ".\src\Labs.js"

function FromB64($b64) {
    return [System.Text.Encoding]::UTF8.GetString([System.Convert]::FromBase64String($b64))
}

if (-not (Test-Path $labsPath)) {
    Write-Host "ERROR: Could not find $labsPath -- run this script from the project root." -ForegroundColor Red
    exit 1
}

# --- Backup first ---
$timestamp = Get-Date -Format "yyyyMMddHHmmss"
$backupPath = ".\src\Labs.js.backup-$timestamp"
Copy-Item $labsPath $backupPath
Write-Host "Backed up Labs.js -> $backupPath" -ForegroundColor Cyan

# --- Load file as raw single string ---
$content = Get-Content $labsPath -Raw

# Normalize to LF for matching (source file may be CRLF); restore CRLF on write if it was CRLF originally
$originalHadCRLF = $content.Contains("`r`n")
if ($originalHadCRLF) {
    $content = $content.Replace("`r`n", "`n")
}

# --- Decode all replacement blocks ---
$stateAnchor          = FromB64 "ICBjb25zdCBbY29tcGxldGluZywgc2V0Q29tcGxldGluZ10gPSB1c2VTdGF0ZShmYWxzZSk7"
$newStateBlock        = FromB64 ""
$handleCompleteAnchor = FromB64 "ICBjb25zdCBoYW5kbGVDb21wbGV0ZSA9IGFzeW5jICgpID0+IHs="
$newEffectBlock       = FromB64 ""
$oldTicketBlock       = FromB64 ""
$newTicketBlock       = FromB64 ""

# ============================================================
# EDIT 1 -- Insert new state hooks
# ============================================================
$anchor1Count = ([regex]::Matches($content, [regex]::Escape($stateAnchor))).Count
if ($anchor1Count -ne 1) {
    Write-Host "ERROR: Expected exactly 1 match for state anchor, found $anchor1Count. Aborting -- no changes made." -ForegroundColor Red
    exit 1
}
$content = $content.Replace($stateAnchor, $newStateBlock)
Write-Host "EDIT 1/3 OK -- new state hooks inserted" -ForegroundColor Green

# ============================================================
# EDIT 2 -- Insert ticket generation effect + submit handler
# ============================================================
$anchor2Count = ([regex]::Matches($content, [regex]::Escape($handleCompleteAnchor))).Count
if ($anchor2Count -ne 1) {
    Write-Host "ERROR: Expected exactly 1 match for handleComplete anchor, found $anchor2Count. Aborting." -ForegroundColor Red
    Write-Host "Restoring original file from backup." -ForegroundColor Yellow
    Copy-Item $backupPath $labsPath -Force
    exit 1
}
$content = $content.Replace($handleCompleteAnchor, $newEffectBlock)
Write-Host "EDIT 2/3 OK -- ticket generation effect + submit handler inserted" -ForegroundColor Green

# ============================================================
# EDIT 3 -- Replace the old multiple-choice ticket branch
# ============================================================
$anchor3Count = ([regex]::Matches($content, [regex]::Escape($oldTicketBlock))).Count
if ($anchor3Count -ne 1) {
    Write-Host "ERROR: Expected exactly 1 match for old ticket block, found $anchor3Count." -ForegroundColor Red
    Write-Host "This likely means Labs.js has changed since the version I was shown." -ForegroundColor Yellow
    Write-Host "Restoring original file from backup. No changes were kept." -ForegroundColor Yellow
    Copy-Item $backupPath $labsPath -Force
    exit 1
}
$content = $content.Replace($oldTicketBlock, $newTicketBlock)
Write-Host "EDIT 3/3 OK -- old multiple-choice ticket branch replaced with AI ticket simulator" -ForegroundColor Green

# --- Restore CRLF if original file used it, then write back BOM-less UTF-8 ---
if ($originalHadCRLF) {
    $content = $content.Replace("`n", "`r`n")
}
[System.IO.File]::WriteAllText((Resolve-Path $labsPath), $content, [System.Text.UTF8Encoding]::new($false))

Write-Host ""
Write-Host "SUCCESS -- Labs.js patched." -ForegroundColor Green
Write-Host "Backup saved at: $backupPath" -ForegroundColor Cyan
Write-Host "Run 'npm start' to test locally before deploying." -ForegroundColor Cyan
